   131→// --- HELPER FUNCTIONS ---
   132→export function extractRecordId(url: string | null | undefined): string | null {
   133→  if (!url) return null;
   134→  // Extrahiere die letzten 24 Hex-Zeichen mit Regex
   135→  const match = url.match(/([a-f0-9]{24})$/i);
   136→  return match ? match[1] : null;
   137→}
   138→
   139→export function createRecordUrl(appId: string, recordId: string): string {
   140→  return `https://my.living-apps.de/rest/apps/${appId}/records/${recordId}`;
   141→}
   142→
   143→async function callApi(method: string, endpoint: string, data?: any) {
   144→  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
   145→    method,
   146→    headers: { 'Content-Type': 'application/json' },
   147→    credentials: 'include',  // Nutze Session Cookies für Auth
   148→    body: data ? JSON.stringify(data) : undefined
   149→  });
   150→  if (!response.ok) throw new Error(await response.text());
   151→  // DELETE returns often empty body or simple status
   152→  if (method === 'DELETE') return true;
   153→  return response.json();
   154→}
