   156→/** Upload a file to LivingApps. Returns the file URL for use in record fields. */
   157→export async function uploadFile(file: File | Blob, filename?: string): Promise<string> {
   158→  const formData = new FormData();
   159→  formData.append('file', file, filename ?? (file instanceof File ? file.name : 'upload'));
   160→  const res = await fetch(`${API_BASE_URL}/files`, {
   161→    method: 'POST',
   162→    credentials: 'include',
   163→    body: formData,
   164→  });
   165→  if (!res.ok) throw new Error(`File upload failed: ${res.status}`);
   166→  const data = await res.json();
   167→  return data.url;
   168→}
