   411→## src/hooks/useDashboardData.ts
   412→```
   413→import { useState, useEffect, useMemo, useCallback } from 'react';
   414→import type { Anmeldungen, Kurse, Raeume, Teilnehmer, Dozenten } from '@/types/app';
   415→import { LivingAppsService } from '@/services/livingAppsService';
   416→
   417→export function useDashboardData() {
   418→  const [anmeldungen, setAnmeldungen] = useState<Anmeldungen[]>([]);
   419→  const [kurse, setKurse] = useState<Kurse[]>([]);
   420→  const [raeume, setRaeume] = useState<Raeume[]>([]);
   421→  const [teilnehmer, setTeilnehmer] = useState<Teilnehmer[]>([]);
   422→  const [dozenten, setDozenten] = useState<Dozenten[]>([]);
   423→  const [loading, setLoading] = useState(true);
   424→  const [error, setError] = useState<Error | null>(null);
   425→
   426→  const fetchAll = useCallback(async () => {
   427→    setError(null);
   428→    try {
   429→      const [anmeldungenData, kurseData, raeumeData, teilnehmerData, dozentenData] = await Promise.all([
   430→        LivingAppsService.getAnmeldungen(),
   431→        LivingAppsService.getKurse(),
   432→        LivingAppsService.getRaeume(),
   433→        LivingAppsService.getTeilnehmer(),
   434→        LivingAppsService.getDozenten(),
   435→      ]);
   436→      setAnmeldungen(anmeldungenData);
   437→      setKurse(kurseData);
   438→      setRaeume(raeumeData);
   439→      setTeilnehmer(teilnehmerData);
   440→      setDozenten(dozentenData);
   441→    } catch (err) {
   442→      setError(err instanceof Error ? err : new Error('Fehler beim Laden der Daten'));
   443→    } finally {
   444→      setLoading(false);
   445→    }
   446→  }, []);
   447→
   448→  useEffect(() => { fetchAll(); }, [fetchAll]);
   449→
   450→  const kurseMap = useMemo(() => {
   451→    const m = new Map<string, Kurse>();
   452→    kurse.forEach(r => m.set(r.record_id, r));
   453→    return m;
   454→  }, [kurse]);
   455→
   456→  const raeumeMap = useMemo(() => {
   457→    const m = new Map<string, Raeume>();
   458→    raeume.forEach(r => m.set(r.record_id, r));
   459→    return m;
   460→  }, [raeume]);
   461→
   462→  const teilnehmerMap = useMemo(() => {
   463→    const m = new Map<string, Teilnehmer>();
   464→    teilnehmer.forEach(r => m.set(r.record_id, r));
   465→    return m;
   466→  }, [teilnehmer]);
   467→
   468→  const dozentenMap = useMemo(() => {
   469→    const m = new Map<string, Dozenten>();
   470→    dozenten.forEach(r => m.set(r.record_id, r));
   471→    return m;
   472→  }, [dozenten]);
   473→
   474→  return { anmeldungen, setAnmeldungen, kurse, setKurse, raeume, setRaeume, teilnehmer, setTeilnehmer, dozenten, setDozenten, loading, error, fetchAll, kurseMap, raeumeMap, teilnehmerMap, dozentenMap };
   475→}
   476→```
