   500→// eslint-disable-next-line @typescript-eslint/no-explicit-any
   501→function resolveDisplay(url: string | undefined, map: Map<string, any>, ...fields: string[]): string {
   502→  if (!url) return '';
   503→  const id = extractRecordId(url);
   504→  if (!id) return '';
   505→  const r = map.get(id);
   506→  if (!r) return '';
   507→  return fields.map(f => String(r.fields[f] ?? '')).join(' ').trim();
