   601→  top_p?: number;
   602→  stop?: string[];
   603→  response_format?: { type: string };
   604→};
   605→
   606→export async function chatCompletion(
   607→  messages: ChatMessage[],
   608→  options: CompletionOptions = {}
   609→): Promise<string> {
   610→  const res = await fetch(AI_ENDPOINT, {
   611→    method: "POST",
   612→    headers: { "Content-Type": "application/json", Accept: "application/json" },
   613→    body: JSON.stringify({ model: AI_MODEL, messages, ...options }),
   614→  });
   615→  if (!res.ok) {
   616→    const body = await res.text();
   617→    throw new Error(`AI API ${res.status}: ${body}`);
   618→  }
   619→  const data = await res.json();
   620→  return data.choices[0].message.content;
   621→}
   622→
   623→export async function safeJsonCompletion<T = unknown>(
   624→  messages: ChatMessage[],
   625→  options: CompletionOptions = {}
   626→): Promise<T> {
   627→  const raw = await chatCompletion(messages, options);
   628→  const match = raw.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
   629→  if (!match) throw new Error(`Expected JSON but got: ${raw.slice(0, 200)}`);
   630→  return JSON.parse(match[0]);
   631→}
   632→
   633→export async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 3): Promise<T> {
   634→  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
   635→    try {
   636→      return await fn();
   637→    } catch (err) {
   638→      if (attempt === maxAttempts) throw err;
   639→      await new Promise((r) => setTimeout(r, 1000 * attempt));
   640→    }
   641→  }
   642→  throw new Error("unreachable");
   643→}
   644→
   645→// --- File encoding helpers ---
   646→
   647→export function fileToDataUri(file: File): Promise<string> {
   648→  return new Promise((resolve, reject) => {
   649→    const reader = new FileReader();
   650→    reader.onload = () => resolve(reader.result as string);
   651→    reader.onerror = () => reject(new Error("Failed to read file"));
   652→    reader.readAsDataURL(file);
   653→  });
   654→}
   655→
   656→export async function urlToDataUri(url: string): Promise<string> {
   657→  const res = await fetch(url);
   658→  const blob = await res.blob();
   659→  return new Promise((resolve, reject) => {
   660→    const reader = new FileReader();
   661→    reader.onload = () => resolve(reader.result as string);
   662→    reader.onerror = () => reject(new Error("Failed to encode file"));
   663→    reader.readAsDataURL(blob);
   664→  });
   665→}
   666→
   667→/** Convert a data URI back to a Blob (for file uploads) */
   668→export function dataUriToBlob(dataUri: string): Blob {
   669→  const [header, base64] = dataUri.split(',');
   670→  const mime = header.match(/:(.*?);/)?.[1] ?? 'application/octet-stream';
   671→  const bytes = atob(base64);
   672→  const arr = new Uint8Array(bytes.length);
   673→  for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
   674→  return new Blob([arr], { type: mime });
   675→}
